const isDataValue = (v: unknown): v is DataValue =>
  typeof v === "boolean" ||
  (typeof v === "string" && v.length <= MAX_DATA_STRING) ||
  (typeof v === "number" && Number.isFinite(v));

/** Whether a value is one of the scopes a remembered value may belong to. */
