/** This place's own structure seed, so every site is the same for every peer. */
const STRUCTURE_SEED = 0x1d57a9e3;

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------
const CAR = "car";
const EXIT_BIND = "exit-car";
const FUEL_ITEM = "fuel";

let started = false;
